### PricingCard.tsx
```tsx
import React, { useState } from 'react';
import { CheckIcon } from 'lucide-react';

import type { Plan } from '../mockData';

type PricingCardProps = {
  plan: Plan;
};

const PricingCard: React.FC<PricingCardProps> = ({ plan }) => {
  const [isYearly, setIsYearly] = useState(false);

  const currentPrice = isYearly ? plan.priceYearly : plan.priceMonthly;

  return (
    <div className="max-w-md w-full bg-white rounded-xl shadow-lg overflow-hidden border border-gray-100">
      <div className="p-6">
        <h2 className="text-xl font-semibold text-gray-900 mb-2">{plan.name}</h2>

        <div className="flex items-baseline justify-between mb-6">
          <span className="text-3xl font-bold text-gray-900">
            ${currentPrice}
          </span>
          <button
            onClick={() => setIsYearly(!isYearly)}
            className="text-sm font-medium text-accent hover:text-accent/80 transition-colors"
          >
            {isYearly ? 'Monthly' : 'Yearly'}
          </button>
        </div>

        <ul className="space-y-3 mb-6">
          {plan.features.map((feature, index) => (
            <li key={index} className="flex items-center gap-2">
              <CheckIcon className="w-4 h-4 text-accent" />
              <span className="text-gray-700 text-sm">{feature}</span>
            </li>
          ))}
        </ul>

        <button
          className="w-full bg-accent text-white py-3 rounded-lg font-semibold hover:bg-accent/90 transition-colors"
        >
          Buy Now
        </button>
      </div>
    </div>
  );
};

export { PricingCard };
```
